import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { AdminProduct } from "@shared/entities";
import { supabase } from "@/lib/supabase";

interface ProductsCtx {
  products: AdminProduct[];
  productsById: Record<string, AdminProduct>;
  getUSDPrice: (id: string) => number;
}

const Ctx = createContext<ProductsCtx | undefined>(undefined);

export function ProductsProvider({ children }: { children: React.ReactNode }) {
  const [products, setProducts] = useState<AdminProduct[]>([]);

  useEffect(() => {
    let mounted = true;
    (async () => {
      const { data, error } = await supabase
        .from("products")
        .select("id,title,description,price,image_url,category_id");
      if (!mounted) return;
      if (error || !data) { setProducts([]); return; }
      const mapped: AdminProduct[] = data.map((row: any) => ({
        id: String(row.id),
        title: row.title,
        description: row.description || "",
        image: row.image_url || "",
        price: { USD: typeof row.price === "string" ? parseFloat(row.price) : Number(row.price || 0) },
        variants: [],
        categoryId: row.category_id ? String(row.category_id) : undefined,
      }));
      setProducts(mapped);
    })();
    return () => { mounted = false; };
  }, []);

  const productsById = useMemo(() => Object.fromEntries(products.map(p=>[p.id, p])), [products]);
  const getUSDPrice = (id: string) => productsById[id]?.price?.USD ?? 0;

  const value = useMemo(()=>({ products, productsById, getUSDPrice }), [products, productsById]);
  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export function useProducts() {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error("useProducts must be used within ProductsProvider");
  return ctx;
}
